def H(child, label, lesson=None):
    h = {'child': child, 'label': label}
    if lesson:
        m = MIS[lesson]
        h['oak'] = {'lesson': lesson, 'misconception': m['misconception'], 'response': m['response']}
    return h

def L(*slugs):
    return [{'slug': s, 'title': MIS[s]['title']} for s in slugs]

def step(name, year, stage, emoji, kind, params, nc, unit, lessons, hints):
    ncy, obj = NC[nc]
    ut, uy = UNITS[unit]
    return {'name': name, 'year': year, 'stage': stage, 'stageEmoji': emoji, 'kind': kind, 'params': params,
            'nc': {'year': ncy, 'objective': obj},
            'oak': {'year': uy, 'unit': unit, 'unitTitle': ut, 'lessons': L(*lessons)},
            'hints': hints}

